# name: power_of_two_specificity
# description: Among sets whose examples are all powers of 2 (2..64), yes rate to non-example powers of 2 minus yes rate to other even non-example targets; observed below the null means people generalise to the remaining powers of 2 less sharply (relative to evens) than the model, above means the model under-commits to the specific rule.
def test_statistic(df):
    p2 = {2, 4, 8, 16, 32, 64}
    sets = df["number_set"].astype(str)
    info = {}
    for s in sets.unique():
        e = [int(x) for x in s.split(",")]
        info[s] = set(e) <= p2
    all_p2 = sets.map(info).to_numpy().astype(bool)
    t = df["target"].astype(int).to_numpy()
    is_ex = np.array([str(x) in s.split(",") for x, s in zip(t, sets)]) if all_p2.any() else np.zeros(len(t), bool)
    is_p2 = np.isin(t, list(p2))
    r = df["rating"].to_numpy().astype(float)
    a = all_p2 & ~is_ex & is_p2
    b = all_p2 & ~is_ex & ~is_p2 & (t % 2 == 0)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())

# name: prev_yes_carryover
# description: Over consecutive row pairs whose trial_index increments by 1, P(yes | previous yes) minus P(yes | previous no); observed above the null means sequential response perseveration that the trial-independent model under-produces, below means alternation.
def test_statistic(df):
    r = df["rating"].to_numpy().astype(float)
    ti = df["trial_index"].to_numpy()
    ok = np.diff(ti) == 1
    prev, cur = r[:-1][ok], r[1:][ok]
    if (prev == 1).sum() == 0 or (prev == 0).sum() == 0:
        return 0.0
    return float(cur[prev == 1].mean() - cur[prev == 0].mean())

# name: two_example_second_minus_first
# description: In 2-example sets with examples at least 10 apart, among non-example targets within 8 of exactly one example, yes rate near the second-presented example minus near the first; observed below the null means the model over-weights the more recent example (or under-weights the first) relative to people, above means people favour the recent example more.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    uniq = sets.unique()
    a1, a2 = {}, {}
    for s in uniq:
        e = [int(x) for x in s.split(",")]
        if len(e) == 2 and abs(e[0] - e[1]) >= 10:
            a1[s], a2[s] = e[0], e[1]
        else:
            a1[s], a2[s] = -1000, -1000
    e1 = sets.map(a1).to_numpy()
    e2 = sets.map(a2).to_numpy()
    t = df["target"].astype(int).to_numpy()
    r = df["rating"].to_numpy().astype(float)
    d1, d2 = np.abs(t - e1), np.abs(t - e2)
    ok = (e1 > 0) & (d1 > 0) & (d2 > 0)
    near1 = ok & (d1 <= 8) & (d2 > 8)
    near2 = ok & (d2 <= 8) & (d1 > 8)
    if near1.sum() == 0 or near2.sum() == 0:
        return 0.0
    return float(r[near2].mean() - r[near1].mean())

# name: outlier_cost_to_rule
# description: Yes rate to non-example targets sharing the majority ones digit in clean sets (3-4 examples all sharing a ones digit) minus the same rate in outlier sets (all but one example share it); observed above the null means one contradicting example hurts rule-following more for people than for the model, below means people are more robust to the outlier than the model.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    kind, dg = {}, {}
    for s in sets.unique():
        e = [int(x) for x in s.split(",")]
        kind[s], dg[s] = 0, -1
        if len(e) >= 3:
            vals, cnt = np.unique([x % 10 for x in e], return_counts=True)
            if cnt.max() == len(e):
                kind[s], dg[s] = 1, int(vals[0])
            elif cnt.max() == len(e) - 1:
                kind[s], dg[s] = 2, int(vals[cnt.argmax()])
    k = sets.map(kind).to_numpy()
    m = sets.map(dg).to_numpy()
    t = df["target"].astype(int).to_numpy()
    is_ex = np.array([str(x) in s.split(",") for x, s in zip(t, sets)])
    r = df["rating"].to_numpy().astype(float)
    rule = (t % 10 == m) & ~is_ex
    a, b = rule & (k == 1), rule & (k == 2)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())

# name: outlier_neighbourhood_yes_rate
# description: In sets of 3-4 examples where all but one share a ones digit (one "outlier" example), the yes rate to non-example targets within 5 of the outlier that do not share the majority ones digit; observed above the null means people generalise around a rule-violating example more than the model (which treats it as noise / a brief switch), below means less.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    od, dg = {}, {}
    for s in sets.unique():
        e = [int(x) for x in s.split(",")]
        od[s], dg[s] = -1000, -1
        if len(e) >= 3:
            d = [x % 10 for x in e]
            vals, cnt = np.unique(d, return_counts=True)
            if cnt.max() == len(e) - 1:
                m = vals[cnt.argmax()]
                od[s] = [x for x in e if x % 10 != m][0]
                dg[s] = int(m)
    o = sets.map(od).to_numpy()
    m = sets.map(dg).to_numpy()
    t = df["target"].astype(int).to_numpy()
    r = df["rating"].to_numpy().astype(float)
    sel = (o > 0) & (np.abs(t - o) <= 5) & (t != o) & (t % 10 != m)
    if sel.sum() == 0:
        return 0.0
    return float(r[sel].mean())
